def canon(S):
    pts=list(S)
    fns=[lambda a,b:(a,b), lambda a,b:(-a,b), lambda a,b:(a,-b), lambda a,b:(-a,-b),
         lambda a,b:(b,a), lambda a,b:(-b,a), lambda a,b:(b,-a), lambda a,b:(-b,-a)]
    outs=[]
    for fn in fns:
